'use strict';
(async()=>{const $=id=>document.getElementById(id),previewId=location.hash.slice(1);let token,preview,project,anchor,key=crypto.randomUUID();const origin='http://127.0.0.1:8774';const node=(tag,str)=>{const n=document.createElement(tag);n.textContent=str;return n};async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Session-Token':token},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||data.message||'请求失败');return data}async function refresh(){const data=await api('/api/user/dashboard');preview=data.previews.find(p=>p.id===previewId);if(!preview||new URL(preview.url).origin!=='http://127.0.0.1:8770')throw Error('此成果尚未配置原型评论适配，请返回协作台。');project=data.projects.find(p=>p.id===preview.projectId);$('title').textContent=project.name+' · V'+project.version+' / '+preview.title;$('state').textContent=preview.current?'当前成果':'历史成果';$('threads').replaceChildren();for(const r of data.requests){let ref;try{ref=JSON.parse(r.reference)}catch{continue}if(ref.previewId!==previewId||r.projectId!==project.id)continue;const a=node('article','');a.append(node('blockquote',ref.page+' · '+ref.quote),node('p',r.body),node('small',new Date(r.createdAt).toLocaleString()));if(r.ack)a.append(node('p','协调方：'+r.ack.plan));for(const reply of r.replies||[])a.append(node('p',reply.source.platform+'：'+reply.body),node('small',reply.evidence||reply.status));$('threads').append(a)}}try{token=(await api('/api/session')).token;await refresh();$('prototype').src=origin+'/';document.querySelector('header a').href='/?project='+project.id+'#experience';}catch(e){$('notice').textContent=e.message;return}addEventListener('message',e=>{if(e.origin!==origin||e.source!==$('prototype').contentWindow||e.data?.type!=='prototype-anchor')return;const a=e.data.anchor;if(typeof a?.quote!=='string'||a.quote.length>400||typeof a.page!=='string'||a.page.length>300)return;anchor={type:'prototype-annotation',previewId,projectId:project.id,previewCreatedAt:preview.createdAt,epoch:project.control.epoch,page:a.page,quote:a.quote,elementId:typeof a.elementId==='string'?a.elementId.slice(0,150):'',kind:a.kind,rect:a.rect};$('anchor').textContent='已选：'+a.quote.slice(0,140);$('body').focus()});setInterval(()=>refresh().catch(e=>$('notice').textContent=e.message),15000);document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('prototype').contentWindow.postMessage({type:'clear-region'},origin);anchor=null;$('anchor').textContent='在左侧原型中选中文字，或点击框选区域。';}});$('region').onclick=()=>$('prototype').contentWindow.postMessage({type:'pick-region'},origin);$('send').onclick=async()=>{if(!anchor||!$('body').value.trim()){$('notice').textContent='请先选中原型位置并填写评论。';return}$('send').disabled=true;try{await api('/api/user/requests',{projectId:project.id,kind:'feedback',body:$('body').value,reference:JSON.stringify(anchor),requestKey:key});key=crypto.randomUUID();$('body').value='';$('notice').textContent='已保存到当前项目协调队列。';await refresh()}catch(e){$('notice').textContent=e.message}finally{$('send').disabled=false}};})();
